export function InvestorAttachmentApprovalPanel({ current, documents, links, linkInvestorDocument, unlinkInvestorDocument }: any) {
  const [documentId, setDocumentId] = useState("");
  const [target, setTarget] = useState<Element | null>(null);
  useEffect(() => { setTarget(document.querySelector(".suppression-note")?.parentElement ?? null); }, [current?.id]);
  if (!current) return null;
  const selectedIds = new Set(links.map((link: any) => link.documentId));
  const selectedDocuments = documents.filter((document: any) => selectedIds.has(document.id));
  const available = documents.filter((document: any) => document.status !== "archived" && !selectedIds.has(document.id));
  const investorType = String(current.type || "").toLowerCase();
  const recommended = available.find((document: any) => String(document.audience || "").toLowerCase().includes(investorType) || (investorType === "vc" && /vc|angel|investor/.test(String(document.audience || "").toLowerCase())));
  const content = <div className="approval-attachments"><div className="kicker">APPROVAL ATTACHMENTS</div><strong>Materials for {current.firmName}</strong><p className="section-subtitle">These files will be included when you approve and send the current investor email through Gmail.</p>{recommended && <div className="attachment-recommendation"><span>Recommended current attachment: <strong>{recommended.category} {recommended.version} — {recommended.name}</strong></span><button className="inline-link" onClick={() => linkInvestorDocument.mutate({ contactId: current.id, documentId: recommended.id })}>Add recommended</button></div>}<div className="attachment-controls"><select value={documentId} onChange={(event) => setDocumentId(event.target.value)}><option value="">Select a current document</option>{available.map((document: any) => <option key={document.id} value={document.id}>{document.category} {document.version} — {document.name}</option>)}</select><Button disabled={!documentId} onClick={() => { linkInvestorDocument.mutate({ contactId: current.id, documentId: Number(documentId) }); setDocumentId(""); }}>Add attachment</Button></div><div className="selected-attachments">{selectedDocuments.length === 0 ? <small>No files selected. Gmail will send the approved email without attachments.</small> : selectedDocuments.map((document: any) => <div key={document.id}><span>{document.category} {document.version} — {document.name}</span><button className="inline-link" onClick={() => unlinkInvestorDocument.mutate({ contactId: current.id, documentId: document.id })}>Remove</button></div>)}</div></div>;
  return target ? createPortal(content, target) : content;
}

export function InvestorPriorityBoard({ contacts }: { contacts: any[] }) {
  const ranked = contacts.map((contact) => ({ contact, intelligence: scoreInvestor(contact) })).sort((a, b) => b.intelligence.score - a.intelligence.score);
  return <Card className="investor-priority-board"><CardHeader><div className="table-head"><div><div className="kicker">INVESTOR WORKSPACE</div><CardTitle>Prioritized prospect list</CardTitle></div><small>Every priority is calculated from saved investor, outreach, and next-action records.</small></div></CardHeader><CardContent>{ranked.length === 0 ? <div className="empty compact"><p>No investor scores yet.</p></div> : <div className="priority-board-list">{ranked.map(({ contact, intelligence }) => <div className="priority-board-row" key={contact.id}><div><strong>{contact.firmName}</strong><small>{contact.relationshipStage} · {contact.geography || "Geography unspecified"}</small></div><div className="priority-board-score"><b>{intelligence.score}</b><span>/100</span></div><span className={`priority-badge ${intelligence.priority.toLowerCase()}`}>{intelligence.priority}</span><small className="priority-board-action">{intelligence.nextMove}</small></div>)}</div>}</CardContent></Card>;
}

const InvestorsV2Base = InvestorsV2;
// This export intentionally composes the established record workspace with the ranked prospect board.
// @ts-ignore Function declarations are mutable at runtime; this replaces the exported workspace binding after capturing its base implementation.
InvestorsV2 = function InvestorsV2WithPriorityBoard(props: any) {
  useEffect(() => {
    const rows = Array.from(document.querySelectorAll(".contacts-card tbody tr"));
    const badges: HTMLElement[] = [];
    rows.forEach((row, index) => {
      const contact = (props.filtered ?? props.contacts ?? [])[index];
      if (!contact) return;
      const intelligence = scoreInvestor(contact);
      const fitCell = row.querySelector("td:nth-child(3)");
      if (!fitCell || fitCell.querySelector(".row-priority-badge")) return;
      const badge = document.createElement("span");
      badge.className = `row-priority-badge ${intelligence.priority.toLowerCase()}`;
      badge.textContent = `${intelligence.score}/100 · ${intelligence.priority}`;
      fitCell.appendChild(badge);
      badges.push(badge);
    });
    return () => badges.forEach((badge) => badge.remove());
  }, [props.filtered, props.contacts]);
  return <><InvestorsV2Base {...props} />{props.current ? <><InvestorPriorityPanel contact={props.current} /><InvestorDnaPanel contact={props.current} /></> : null}<InvestorPriorityBoard contacts={props.filtered ?? props.contacts ?? []} /></>;
};
