export function FundraisingFunnelSimulator() {
  const [assumptions, setAssumptions] = useState({ prospects: 1000, qualificationRate: 50, contactRate: 50, responseRate: 40, conversationRate: 50, diligenceRate: 50, meetingRate: 40, termSheetRate: 30, targetCapital: 1_000_000, averageCheck: 250_000 });
  const simulation = simulateFunnel(assumptions);
  const projectedCapital = simulation.termSheets * assumptions.averageCheck;
  const capitalGap = Math.max(0, assumptions.targetCapital - projectedCapital);
  const stageRows = [["Identified prospects", simulation.identified], ["Qualified", simulation.qualified], ["Contacted", simulation.contacted], ["Responses", simulation.responses], ["Conversations", simulation.conversations], ["Diligence", simulation.diligence], ["Meetings", simulation.meetings], ["Projected commitments", simulation.termSheets]];
  const update = (key: keyof typeof assumptions, value: string) => setAssumptions((current) => ({ ...current, [key]: Math.max(0, Number(value) || 0) }));
  const money = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value);
  return <Card className="funnel-simulator"><CardHeader><div className="table-head"><div><div className="kicker">CAPITAL-PLANNING SIMULATOR</div><CardTitle>Model the fundraising path</CardTitle></div><small>Every projection comes from the editable assumptions below; no historical conversion rate is implied.</small></div></CardHeader><CardContent><div className="simulator-layout"><div className="simulator-inputs"><div className="simulator-capital-grid"><label>Target capital<input type="number" min="0" value={assumptions.targetCapital} onChange={(event) => update("targetCapital", event.target.value)} /></label><label>Average check<input type="number" min="0" value={assumptions.averageCheck} onChange={(event) => update("averageCheck", event.target.value)} /></label><label>Starting prospects<input type="number" min="0" value={assumptions.prospects} onChange={(event) => update("prospects", event.target.value)} /></label></div><div className="simulator-rate-grid">{[["qualificationRate", "Identify → qualified"], ["contactRate", "Qualified → contacted"], ["responseRate", "Contacted → response"], ["conversationRate", "Response → conversation"], ["diligenceRate", "Conversation → diligence"], ["meetingRate", "Diligence → meeting"], ["termSheetRate", "Meeting → commitment"]].map(([key, label]) => <label key={key}>{label}<span><input type="number" min="0" max="100" value={assumptions[key as keyof typeof assumptions]} onChange={(event) => update(key as keyof typeof assumptions, event.target.value)} />%</span></label>)}</div></div><div className="simulator-output"><div className="simulator-capital-summary"><div><span>Projected capital</span><strong>{money(projectedCapital)}</strong></div><div><span>Target capital</span><strong>{money(assumptions.targetCapital)}</strong></div><div><span>Remaining gap</span><strong>{money(capitalGap)}</strong></div></div><div className="simulator-stages">{stageRows.map(([label, count]) => <div key={String(label)}><span>{label}</span><b>{count}</b></div>)}</div><small className="simulator-note">At {money(assumptions.averageCheck)} per projected commitment, this model expects {simulation.termSheets} commitments. Change an assumption to see the direct operational effect.</small></div></div></CardContent></Card>;
}
