type InternalProjectsView = "overview" | "projects" | "capital_needs" | "economics" | "cedarwood_proforma" | "cedarwood_schedule_financing" | "historical_budget" | "capital_stack" | "documents";
type ProjectEconomicsPanel = "model" | "cedarwood_proforma" | "cedarwood_schedule_financing" | "historical_budget";

export function InternalProjectsWorkspace({ projects, capitalNeeds, capitalNeedStrategies, capitalStack, documents, documentLinks, roiProjects, capitalOpportunities, historicalPlanningBudgetComparison, cedarwoodPlanningWbsSummary, cedarwoodHistoricalScenarioId, cedarwoodScheduleFinancingSnapshot, saveCedarwoodPlanningSchedule, saveCedarwoodPlanningFinancing, refreshCedarwoodPlanningWbs, selectedProjectId, onProjectSelect, onOpenRoi, createProject, updateProject, seedProjects, saveCapitalNeed, linkDocument, unlinkDocument, updateCapitalOpportunity, projectEconomicsModel, projectEconomicsInputs, projectEconomicsMonthlyItems, projectEconomicsReadiness, projectEconomicsInputDocumentLinks, initializeProjectEconomicsModel, saveProjectEconomicsInput, saveProjectEconomicsMonthlyItem, linkProjectEconomicsInputDocument, unlinkProjectEconomicsInputDocument, initialView }: any) {
  const legacyEconomicsPanel: Record<string, ProjectEconomicsPanel> = { cedarwood_proforma: "cedarwood_proforma", cedarwood_schedule_financing: "cedarwood_schedule_financing", historical_budget: "historical_budget" };
  const [view, setView] = useState<InternalProjectsView>(() => legacyEconomicsPanel[initialView] ? "economics" : initialView || "overview");
  const [economicsPanel, setEconomicsPanel] = useState<ProjectEconomicsPanel>(() => legacyEconomicsPanel[initialView] || "model");
  const [newProject, setNewProject] = useState({ name: "", code: "", type: "", location: "", status: "planning", stage: "concept", sponsor: "", totalCost: "", totalCostState: "missing", requirement: "", requirementState: "missing", targetCompletion: "", ffProject: "", roiProjectId: "", description: "" });
  const [needDraft, setNeedDraft] = useState({ name: "", category: "other", amount: "", state: "missing", strategies: [] as string[], notes: "" });
  const [documentId, setDocumentId] = useState("");
  const [opportunityId, setOpportunityId] = useState("");
  const [editingProject, setEditingProject] = useState<any>(null);
  const project = projects.find((item: any) => item.id === (selectedProjectId ?? projects[0]?.id));
  const totalRequired = projects.reduce((sum: number, item: any) => sum + (item.capitalRequirementDataState === "missing" ? 0 : item.capitalRequirement ?? 0), 0);
  const linkedDocumentIds = new Set(documentLinks.map((link: any) => link.documentId));
  const availableDocuments = documents.filter((document: any) => document.status === "current" && !linkedDocumentIds.has(document.id));
  const currentDocumentLinks = documents.filter((document: any) => linkedDocumentIds.has(document.id));
  const linkedOpportunityIds = new Set((capitalStack?.linkedOpportunities ?? []).map((opportunity: any) => opportunity.id));
  const availableOpportunities = capitalOpportunities.filter((opportunity: any) => opportunity.stage !== "passed" && !linkedOpportunityIds.has(opportunity.id));
  const tabs: Array<[InternalProjectsView, string, string]> = [["overview", "Overview", "Portfolio context"], ["projects", "Projects", "Identity and lifecycle"], ["capital_needs", "Capital Needs", "Uses and eligible strategies"], ["economics", "Project Economics", "Model and scenario tools"], ["capital_stack", "Capital Stack", "Staged funding sources"], ["documents", "Documents", "Project context"]];
  const isCedarwood = project?.projectName === "Cedarwood Flats";
  const cedarwoodEconomicsPanels: Array<[ProjectEconomicsPanel, string, string]> = [["cedarwood_proforma", "Historical pro forma", "WBS and control totals"], ["cedarwood_schedule_financing", "Schedule + debt", "Monthly plan and charts"]];
  const economicsPanels: Array<[ProjectEconomicsPanel, string, string]> = [
    ["model", "Model shell", "Inputs and governed timing"],
    ...cedarwoodEconomicsPanels.filter(() => isCedarwood),
    ["historical_budget", "Portfolio context", "Historical scenario comparison"],
  ];
  useEffect(() => { if (projects.length && !projects.some((item: any) => item.id === selectedProjectId)) onProjectSelect(projects[0].id); }, [projects, selectedProjectId, onProjectSelect]);
  useEffect(() => { const requestedPanel = legacyEconomicsPanel[initialView]; const cedarwoodPanel = requestedPanel === "cedarwood_proforma" || requestedPanel === "cedarwood_schedule_financing"; if (requestedPanel && (!cedarwoodPanel || isCedarwood)) { setView("economics"); setEconomicsPanel(requestedPanel); } }, [initialView, isCedarwood]);
  useEffect(() => { if (!isCedarwood && ["cedarwood_proforma", "cedarwood_schedule_financing"].includes(economicsPanel)) setEconomicsPanel("model"); }, [isCedarwood, economicsPanel]);
  useEffect(() => { if (project) setEditingProject({ name: project.projectName, code: project.projectCode || "", type: project.projectType || "", location: project.location || "", status: project.projectStatus, stage: project.developmentStage, sponsor: project.sponsorEntity || "", totalCost: project.totalProjectCost ?? "", totalCostState: project.totalProjectCostDataState, requirement: project.capitalRequirement ?? "", requirementState: project.capitalRequirementDataState, targetCompletion: project.targetCompletionAt ? new Date(project.targetCompletionAt).toISOString().slice(0, 10) : "", ffProject: project.linkedFfProject || "", roiProjectId: project.roiProjectId ? String(project.roiProjectId) : "", description: project.description || "" }); }, [project?.id, project?.updatedAt]);
  const money = (value: number | null | undefined) => value === null || value === undefined ? "Not yet recorded" : formatCapitalAmount(value);
  const toggleStrategy = (strategy: string) => setNeedDraft((current) => ({ ...current, strategies: current.strategies.includes(strategy) ? current.strategies.filter((item) => item !== strategy) : [...current.strategies, strategy] }));
  const createProjectRecord = () => { if (!newProject.name.trim()) return; createProject.mutate({ projectName: newProject.name.trim(), projectCode: newProject.code.trim() || undefined, projectType: newProject.type.trim() || undefined, location: newProject.location.trim() || undefined, projectStatus: newProject.status, developmentStage: newProject.stage, sponsorEntity: newProject.sponsor.trim() || undefined, totalProjectCost: roiNumber(newProject.totalCost), totalProjectCostDataState: newProject.totalCostState, capitalRequirement: roiNumber(newProject.requirement), capitalRequirementDataState: newProject.requirementState, targetCompletionAt: newProject.targetCompletion ? new Date(`${newProject.targetCompletion}T00:00:00`) : undefined, linkedFfProject: newProject.ffProject.trim() || undefined, roiProjectId: newProject.roiProjectId ? Number(newProject.roiProjectId) : undefined, description: newProject.description.trim() || undefined }); setNewProject({ name: "", code: "", type: "", location: "", status: "planning", stage: "concept", sponsor: "", totalCost: "", totalCostState: "missing", requirement: "", requirementState: "missing", targetCompletion: "", ffProject: "", roiProjectId: "", description: "" }); };
  const saveProjectRecord = () => { if (!project || !editingProject?.name?.trim()) return; updateProject.mutate({ id: project.id, projectName: editingProject.name.trim(), projectCode: editingProject.code.trim() || undefined, projectType: editingProject.type.trim() || undefined, location: editingProject.location.trim() || undefined, projectStatus: editingProject.status, developmentStage: editingProject.stage, sponsorEntity: editingProject.sponsor.trim() || undefined, totalProjectCost: roiNumber(String(editingProject.totalCost)), totalProjectCostDataState: editingProject.totalCostState, capitalRequirement: roiNumber(String(editingProject.requirement)), capitalRequirementDataState: editingProject.requirementState, targetCompletionAt: editingProject.targetCompletion ? new Date(`${editingProject.targetCompletion}T00:00:00`) : undefined, linkedFfProject: editingProject.ffProject.trim() || undefined, roiProjectId: editingProject.roiProjectId ? Number(editingProject.roiProjectId) : null, description: editingProject.description.trim() || undefined }); };
  return <section className="internal-projects-workspace" aria-label="Internal Projects workspace">
    <div className="internal-projects-ribbon"><div><div className="kicker">PROJECT CONTEXT · NOT A CAPITAL PATH</div><h2>Internal Projects</h2><p>Define what CE/FF is building or investing in, then connect recorded capital needs, source opportunities, ROI / Returns models, and existing documents without turning projects into a fundraising pipeline.</p></div><div className="internal-projects-tabs" role="tablist" aria-label="Internal Projects capabilities">{tabs.map(([id, label, description]) => <button key={id} type="button" role="tab" aria-selected={view === id} className={view === id ? "active" : ""} onClick={() => setView(id)}><b>{label}</b><span>{description}</span></button>)}</div></div>
    <div className="internal-project-picker"><label>Active Internal Project<select aria-label="Select Internal Project" value={project?.id ?? ""} onChange={(event) => onProjectSelect(Number(event.target.value))}><option value="" disabled>Select Internal Project</option>{projects.map((item: any) => <option key={item.id} value={item.id}>{item.projectName}</option>)}</select></label><span>{projects.length} project{projects.length === 1 ? "" : "s"} recorded</span></div>
    {view === "overview" && <div className="internal-projects-overview"><div className="internal-project-stats"><RoiMetric label="ACTIVE PROJECTS" value={String(projects.filter((item: any) => item.projectStatus === "active").length)} note="Recorded project lifecycle" /><RoiMetric label="RECORDED REQUIREMENT" value={formatCapitalAmount(totalRequired)} note="Excludes missing project requirements" /><RoiMetric label="SELECTED COMMITTED" value={money(capitalStack?.totals?.committed)} note="Recorded opportunities only" /><RoiMetric label="SELECTED FUNDED" value={money(capitalStack?.totals?.funded)} note="Actual funded capital only" /></div><div className="internal-projects-rule"><div className="kicker">OPERATING RELATIONSHIP</div><b>Internal Project → Capital Needs → Capital Opportunities → Capital Stack → ROI / Returns</b><p>Potential, commitment, funded capital, project cost, cash flow, and return remain distinct. Capital needs record intended uses; they do not create capital opportunities or amounts by assumption.</p></div>{project && <div className="internal-project-known-context"><div><div className="kicker">VERIFIED PROJECT PROGRAM</div><b>{project.projectName}</b><p>{project.knownProgramSummary || "Known program information is not yet defined."}</p>{[project.programUnitCount !== null && project.programUnitCount !== undefined ? `${project.programUnitCount} units` : null, project.programBuildingCount !== null && project.programBuildingCount !== undefined ? `${project.programBuildingCount} buildings` : null, project.programUnitsPerBuilding !== null && project.programUnitsPerBuilding !== undefined ? `${project.programUnitsPerBuilding} units / building` : null, project.programAreaSqFt !== null && project.programAreaSqFt !== undefined ? `${project.programAreaSqFt.toLocaleString()} SF` : null].filter(Boolean).length ? <small>{[project.programUnitCount !== null && project.programUnitCount !== undefined ? `${project.programUnitCount} units` : null, project.programBuildingCount !== null && project.programBuildingCount !== undefined ? `${project.programBuildingCount} buildings` : null, project.programUnitsPerBuilding !== null && project.programUnitsPerBuilding !== undefined ? `${project.programUnitsPerBuilding} units / building` : null, project.programAreaSqFt !== null && project.programAreaSqFt !== undefined ? `${project.programAreaSqFt.toLocaleString()} SF` : null].filter(Boolean).join(" · ")}</small> : null}{project.programFootprintDescription ? <small>{project.programFootprintDescription}</small> : null}</div><div><div className="kicker">FACTORY FOUNDATION RELATIONSHIP</div><span className={`roi-state ${project.factoryFoundationRelationshipState === "linked" ? "actual" : project.factoryFoundationRelationshipState === "contextual" ? "projected" : "missing"}`}>{project.factoryFoundationRelationshipState || "missing"}</span><p>{project.factoryFoundationRelationship || "No Factory Foundation relationship recorded."}</p></div></div>}<div className="internal-project-list">{projects.map((item: any) => <button type="button" key={item.id} className={item.id === project?.id ? "selected" : ""} onClick={() => { onProjectSelect(item.id); setView("projects"); }}><b>{item.projectName}</b><span>{item.projectType || "Project type not yet recorded"} · {item.projectStatus.replaceAll("_", " ")}</span><small>Capital requirement: {item.capitalRequirementDataState === "missing" ? "Not yet recorded" : money(item.capitalRequirement)}</small></button>)}</div></div>}
    {view === "projects" && <div className="internal-projects-projects"><Card><CardHeader><div className="table-head"><div><div className="kicker">ESTABLISHED CE/FF PROJECT RECORDS</div><CardTitle>Seed authoritative context without assumptions</CardTitle></div><Button disabled={seedProjects.isPending} onClick={() => seedProjects.mutate()}>{seedProjects.isPending ? "Seeding…" : "Seed six established projects"}</Button></div><p className="section-subtitle">The seed creates only the approved Internal Project records and verified program context. It does not add a cost, capital need, capital opportunity, funding, ROI model, cash flow, or return.</p></CardHeader><CardContent><div className="internal-project-form-grid"><Input placeholder="Project name *" value={newProject.name} onChange={(event) => setNewProject({ ...newProject, name: event.target.value })} /><Input placeholder="Project ID / code" value={newProject.code} onChange={(event) => setNewProject({ ...newProject, code: event.target.value })} /><Input placeholder="Project type" value={newProject.type} onChange={(event) => setNewProject({ ...newProject, type: event.target.value })} /><Input placeholder="Location" value={newProject.location} onChange={(event) => setNewProject({ ...newProject, location: event.target.value })} /><select value={newProject.status} onChange={(event) => setNewProject({ ...newProject, status: event.target.value })}><option value="planning">Planning</option><option value="active">Active</option><option value="on_hold">On hold</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><select value={newProject.stage} onChange={(event) => setNewProject({ ...newProject, stage: event.target.value })}><option value="concept">Concept</option><option value="predevelopment">Predevelopment</option><option value="development">Development</option><option value="construction">Construction</option><option value="commissioning">Commissioning</option><option value="operations">Operations</option><option value="completed">Completed</option></select><Input placeholder="Sponsor / entity" value={newProject.sponsor} onChange={(event) => setNewProject({ ...newProject, sponsor: event.target.value })} /><Input type="date" aria-label="Target completion" value={newProject.targetCompletion} onChange={(event) => setNewProject({ ...newProject, targetCompletion: event.target.value })} /><Input inputMode="numeric" placeholder="Total project cost" value={newProject.totalCost} onChange={(event) => setNewProject({ ...newProject, totalCost: event.target.value })} /><select value={newProject.totalCostState} onChange={(event) => setNewProject({ ...newProject, totalCostState: event.target.value })}><option value="missing">Cost state: missing</option><option value="actual">Cost state: actual</option><option value="projected">Cost state: projected</option><option value="estimated">Cost state: estimated</option></select><Input inputMode="numeric" placeholder="Capital requirement" value={newProject.requirement} onChange={(event) => setNewProject({ ...newProject, requirement: event.target.value })} /><select value={newProject.requirementState} onChange={(event) => setNewProject({ ...newProject, requirementState: event.target.value })}><option value="missing">Requirement state: missing</option><option value="actual">Requirement state: actual</option><option value="projected">Requirement state: projected</option><option value="estimated">Requirement state: estimated</option></select><Input placeholder="Linked FF project" value={newProject.ffProject} onChange={(event) => setNewProject({ ...newProject, ffProject: event.target.value })} /><select value={newProject.roiProjectId} onChange={(event) => setNewProject({ ...newProject, roiProjectId: event.target.value })}><option value="">No ROI / Returns model linked</option>{roiProjects.map((item: any) => <option key={item.id} value={item.id}>{item.projectName}</option>)}</select></div><Textarea rows={2} placeholder="Project context / description" value={newProject.description} onChange={(event) => setNewProject({ ...newProject, description: event.target.value })} /><Button disabled={!newProject.name.trim() || createProject.isPending} onClick={createProjectRecord}>{createProject.isPending ? "Creating…" : "Create Internal Project"}</Button></CardContent></Card>{project && editingProject && <Card><CardHeader><div className="kicker">EDIT SELECTED PROJECT</div><CardTitle>{project.projectName}</CardTitle></CardHeader><CardContent><div className="internal-project-form-grid"><Input value={editingProject.name} onChange={(event) => setEditingProject({ ...editingProject, name: event.target.value })} /><Input placeholder="Project ID / code" value={editingProject.code} onChange={(event) => setEditingProject({ ...editingProject, code: event.target.value })} /><Input placeholder="Project type" value={editingProject.type} onChange={(event) => setEditingProject({ ...editingProject, type: event.target.value })} /><Input placeholder="Location" value={editingProject.location} onChange={(event) => setEditingProject({ ...editingProject, location: event.target.value })} /><select value={editingProject.status} onChange={(event) => setEditingProject({ ...editingProject, status: event.target.value })}><option value="planning">Planning</option><option value="active">Active</option><option value="on_hold">On hold</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><select value={editingProject.stage} onChange={(event) => setEditingProject({ ...editingProject, stage: event.target.value })}><option value="concept">Concept</option><option value="predevelopment">Predevelopment</option><option value="development">Development</option><option value="construction">Construction</option><option value="commissioning">Commissioning</option><option value="operations">Operations</option><option value="completed">Completed</option></select><Input placeholder="Sponsor / entity" value={editingProject.sponsor} onChange={(event) => setEditingProject({ ...editingProject, sponsor: event.target.value })} /><Input type="date" value={editingProject.targetCompletion} onChange={(event) => setEditingProject({ ...editingProject, targetCompletion: event.target.value })} /><Input inputMode="numeric" placeholder="Total project cost" value={editingProject.totalCost} onChange={(event) => setEditingProject({ ...editingProject, totalCost: event.target.value })} /><select value={editingProject.totalCostState} onChange={(event) => setEditingProject({ ...editingProject, totalCostState: event.target.value })}><option value="missing">Cost state: missing</option><option value="actual">Cost state: actual</option><option value="projected">Cost state: projected</option><option value="estimated">Cost state: estimated</option></select><Input inputMode="numeric" placeholder="Capital requirement" value={editingProject.requirement} onChange={(event) => setEditingProject({ ...editingProject, requirement: event.target.value })} /><select value={editingProject.requirementState} onChange={(event) => setEditingProject({ ...editingProject, requirementState: event.target.value })}><option value="missing">Requirement state: missing</option><option value="actual">Requirement state: actual</option><option value="projected">Requirement state: projected</option><option value="estimated">Requirement state: estimated</option></select><Input placeholder="Linked FF project" value={editingProject.ffProject} onChange={(event) => setEditingProject({ ...editingProject, ffProject: event.target.value })} /><select value={editingProject.roiProjectId} onChange={(event) => setEditingProject({ ...editingProject, roiProjectId: event.target.value })}><option value="">No ROI / Returns model linked</option>{roiProjects.map((item: any) => <option key={item.id} value={item.id}>{item.projectName}</option>)}</select></div><Textarea rows={2} placeholder="Project context / description" value={editingProject.description} onChange={(event) => setEditingProject({ ...editingProject, description: event.target.value })} /><Button disabled={!editingProject.name.trim() || updateProject.isPending} onClick={saveProjectRecord}>{updateProject.isPending ? "Saving…" : "Save project context"}</Button></CardContent></Card>}</div>}
    {view === "capital_needs" && <div className="internal-projects-needs">{!project ? <div className="empty-state">Create an Internal Project before recording capital needs.</div> : <><Card><CardHeader><div className="kicker">PROJECT USES OF CAPITAL</div><CardTitle>{project.projectName}</CardTitle><p className="section-subtitle">A need can have multiple eligible strategies. Its amount contributes once to the project requirement and is not a capital commitment.</p></CardHeader><CardContent><div className="internal-project-form-grid"><Input placeholder="Requirement name *" value={needDraft.name} onChange={(event) => setNeedDraft({ ...needDraft, name: event.target.value })} /><Input placeholder="Category (land, equipment, working capital…)" value={needDraft.category} onChange={(event) => setNeedDraft({ ...needDraft, category: event.target.value })} /><Input inputMode="numeric" placeholder="Amount" value={needDraft.amount} onChange={(event) => setNeedDraft({ ...needDraft, amount: event.target.value })} /><select value={needDraft.state} onChange={(event) => setNeedDraft({ ...needDraft, state: event.target.value })}><option value="missing">Missing</option><option value="actual">Actual</option><option value="projected">Projected</option><option value="estimated">Estimated</option></select></div><Textarea rows={2} placeholder="Need context / sourcing notes" value={needDraft.notes} onChange={(event) => setNeedDraft({ ...needDraft, notes: event.target.value })} /><div className="internal-project-strategy-checks">{[["equity", "Equity"], ["facility_jv", "JV / Facility"], ["equipment_finance", "Equipment Finance"], ["grants", "Grants & Incentives"], ["other", "Other"]].map(([id, label]) => <label key={id}><input type="checkbox" checked={needDraft.strategies.includes(id)} onChange={() => toggleStrategy(id)} />{label}</label>)}</div><Button disabled={!needDraft.name.trim() || saveCapitalNeed.isPending} onClick={() => { if (!project) return; saveCapitalNeed.mutate({ internalProjectId: project.id, requirementName: needDraft.name.trim(), requirementCategory: needDraft.category.trim() || "other", amount: roiNumber(needDraft.amount), amountDataState: needDraft.state, notes: needDraft.notes.trim() || undefined, sortOrder: capitalNeeds.length, strategyTypes: needDraft.strategies as any }); setNeedDraft({ name: "", category: "other", amount: "", state: "missing", strategies: [], notes: "" }); }}>{saveCapitalNeed.isPending ? "Recording…" : "Record capital need"}</Button></CardContent></Card><div className="internal-project-needs-list">{capitalNeeds.map((need: any) => <article key={need.id}><div><b>{need.requirementName}</b><span>{need.requirementCategory}</span><small>{capitalNeedStrategies.filter((strategy: any) => strategy.capitalNeedId === need.id).map((strategy: any) => strategy.strategyType.replaceAll("_", " ")).join(" · ") || "No capital strategy recorded"}</small></div><div><strong>{need.amountDataState === "missing" ? "Not yet recorded" : money(need.amount)}</strong><span className={`roi-state ${need.amountDataState}`}>{need.amountDataState}</span></div></article>)}{!capitalNeeds.length && <div className="empty-state">No capital needs recorded. Add what the project needs before matching it to source opportunities.</div>}</div></>}</div>}
    {view === "economics" && <div className="internal-projects-economics">{!project ? <div className="empty-state">Create an Internal Project before linking ROI / Returns.</div> : <><Card><CardHeader><div className="kicker">ECONOMICS FEED ROI / RETURNS</div><CardTitle>{project.projectName}</CardTitle></CardHeader><CardContent><p className="section-subtitle">Internal Projects owns project context and governed project-model inputs. ROI / Returns remains the calculation authority for revenue, cost, cash flow, ROI, IRR, payback, distributions, and multiple.</p>{project.roiProjectId ? <div className="internal-projects-linked-model"><b>{roiProjects.find((item: any) => item.id === project.roiProjectId)?.projectName || "Linked ROI / Returns model"}</b><span>Linked model ID {project.roiProjectId}</span><Button onClick={onOpenRoi}>Open ROI / Returns</Button></div> : <div className="empty-state">No ROI / Returns model linked. The governed project model remains distinct from an ROI calculation model.</div>}</CardContent></Card><div className="project-economics-panel-tabs" role="tablist" aria-label={`${project.projectName} project economics tools`}>{economicsPanels.map(([id, label, description]) => <button key={id} type="button" role="tab" aria-selected={economicsPanel === id} className={economicsPanel === id ? "active" : ""} onClick={() => setEconomicsPanel(id)}><b>{label}</b><span>{description}</span></button>)}</div>{economicsPanel === "model" && <ProjectEconomicsModelShell project={project} model={projectEconomicsModel} inputs={projectEconomicsInputs} monthlyItems={projectEconomicsMonthlyItems} readiness={projectEconomicsReadiness} documents={documents} inputDocumentLinks={projectEconomicsInputDocumentLinks} initializeModel={initializeProjectEconomicsModel} saveInput={saveProjectEconomicsInput} saveMonthlyItem={saveProjectEconomicsMonthlyItem} linkInputDocument={linkProjectEconomicsInputDocument} unlinkInputDocument={unlinkProjectEconomicsInputDocument} onOpenRoi={onOpenRoi} />}{economicsPanel === "cedarwood_proforma" && isCedarwood && <CedarwoodHistoricalProForma summary={cedarwoodPlanningWbsSummary} scenarioId={cedarwoodHistoricalScenarioId} refresh={refreshCedarwoodPlanningWbs} />}{economicsPanel === "cedarwood_schedule_financing" && isCedarwood && <CedarwoodScheduleFinancing scenarioId={cedarwoodHistoricalScenarioId} snapshot={cedarwoodScheduleFinancingSnapshot} wbsSummary={cedarwoodPlanningWbsSummary} saveSchedule={saveCedarwoodPlanningSchedule} saveFinancing={saveCedarwoodPlanningFinancing} />}{economicsPanel === "historical_budget" && <div className="internal-projects-economics"><Card><CardHeader><div className="kicker">SIX-PROJECT COMPARISON · HISTORICAL PLANNING ONLY</div><CardTitle>Comparable context without creating a portfolio budget total</CardTitle></CardHeader><CardContent><p className="section-subtitle">Each amount remains in its own historical scenario. The view never sums unlike measures, never converts a planning figure into a current capital need, and does not calculate current ROI, IRR, payback, commitments, or funded capital.</p></CardContent></Card><div className="internal-projects-document-list">{historicalPlanningBudgetComparison.map((row: any) => <article key={row.projectId}><div><b>{row.projectName}</b><span>{row.hasRecoverableHistoricalPlanning ? `${row.scenarios.length} historical planning scenario${row.scenarios.length === 1 ? "" : "s"} · estimated · effective date unknown` : "Historical financial scenario unavailable"}</span><small>{row.hasRecoverableHistoricalPlanning ? row.scenarios.map((scenario: any) => `${scenario.scenarioName}: ${scenario.primaryMetric ? `${scenario.primaryMetric.metric.replaceAll("_", " ")} ${formatCapitalAmount(scenario.primaryMetric.value)}` : "no supported amount"}`).join(" | ") : "Recover dated source material before entering an amount."}</small></div><div><strong>{row.hasRecoverableHistoricalPlanning ? "Historical only" : "Unavailable"}</strong><span className={`roi-state ${row.hasRecoverableHistoricalPlanning ? "estimated" : "missing"}`}>{row.hasRecoverableHistoricalPlanning ? "estimated" : "missing"}</span></div></article>)}</div><div className="internal-projects-rule"><div className="kicker">COMPARISON BOUNDARY</div><b>Scenario amounts are reference points, not additive portfolio capital requirements.</b><p>All scenarios derive from the user-supplied historical planning briefing, carry null effective dates, and remain source-labeled pending recovery of underlying dated model materials.</p></div></div>}</>}</div>}
    {view === "capital_stack" && <div className="internal-projects-stack">{!project ? <div className="empty-state">Create an Internal Project before reviewing its capital stack.</div> : <><div className="internal-project-stats"><RoiMetric label="PROJECT REQUIREMENT" value={money(capitalStack?.totals?.capitalRequirement)} note="Needs total when complete; otherwise recorded project requirement" /><RoiMetric label="POTENTIAL PIPELINE" value={money(capitalStack?.totals?.potential)} note="Decision context only · excluded from gap" /><RoiMetric label="COMMITTED" value={money(capitalStack?.totals?.committed)} note="Recorded source commitments" /><RoiMetric label="FUNDED" value={money(capitalStack?.totals?.funded)} note="Actual funded capital only" /></div><div className="internal-projects-stack-table"><div className="internal-projects-stack-row head"><span>Capital strategy</span><span>Eligible needs*</span><span>Potential</span><span>Committed</span><span>Funded</span><span>Sources</span></div>{(capitalStack?.rows ?? []).map((row: any) => <div className="internal-projects-stack-row" key={row.strategyType}><b>{row.strategyType === "facility_jv" ? "JV / Facility" : row.strategyType === "equipment_finance" ? "Equipment Finance" : row.strategyType === "grants" ? "Grants & Incentives" : row.strategyType === "other" ? "Other" : "Equity"}</b><span>{money(row.target)}</span><span>{money(row.potential)}</span><span>{money(row.committed)}</span><span>{money(row.funded)}</span><span>{row.opportunityCount} linked</span></div>)}</div><small className="internal-projects-footnote">*Eligible needs may appear under more than one strategy. They are never added across strategies; total project requirement is calculated once from needs when all need amounts are recorded.</small><div className="internal-projects-link-opportunity"><div><div className="kicker">EXPLICIT CAPITAL-OPPORTUNITY LINK</div><p>Attach a recorded source opportunity to this project. This does not create or change the opportunity’s capital amount, stage, probability, commitment, or funding.</p></div><select value={opportunityId} onChange={(event) => setOpportunityId(event.target.value)}><option value="">Select recorded opportunity</option>{availableOpportunities.map((opportunity: any) => <option key={opportunity.id} value={opportunity.id}>{opportunity.organizationName} · {opportunity.capitalPath.replaceAll("_", " ")}</option>)}</select><Button disabled={!opportunityId || updateCapitalOpportunity.isPending} onClick={() => { updateCapitalOpportunity.mutate({ id: Number(opportunityId), internalProjectId: project.id }); setOpportunityId(""); }}>Attach to project</Button></div><div className="internal-projects-linked-opportunities">{(capitalStack?.linkedOpportunities ?? []).map((opportunity: any) => <article key={opportunity.id}><b>{opportunity.organizationName}</b><span>{opportunity.capitalPath.replaceAll("_", " ")} · {opportunity.linkReason}</span><small>Potential {money(opportunity.requestedAmount)} · Committed {money(opportunity.committedAmount)} · Funded {money(opportunity.fundedAmount)}</small></article>)}{!(capitalStack?.linkedOpportunities ?? []).length && <div className="empty-state">No source opportunity is connected yet. Explicit project links and exact recorded project/facility-name matches are eligible.</div>}</div></>}</div>}
    {view === "documents" && <div className="internal-projects-documents">{!project ? <div className="empty-state">Create an Internal Project before contextualizing documents.</div> : <><Card><CardHeader><div className="kicker">PROJECT DOCUMENT CONTEXT</div><CardTitle>{project.projectName}</CardTitle><p className="section-subtitle">Document files and metadata remain in the central Document Library. This only adds project context.</p></CardHeader><CardContent><div className="inline-form"><select value={documentId} onChange={(event) => setDocumentId(event.target.value)}><option value="">Select current library document</option>{availableDocuments.map((document: any) => <option key={document.id} value={document.id}>{document.name} · {document.version}</option>)}</select><Button disabled={!documentId || linkDocument.isPending} onClick={() => { linkDocument.mutate({ internalProjectId: project.id, documentId: Number(documentId) }); setDocumentId(""); }}>Link document</Button></div></CardContent></Card><div className="internal-projects-document-list">{currentDocumentLinks.map((document: any) => <article key={document.id}><div><b>{document.name}</b><span>{document.category} · {document.version}</span><small>{document.description || document.purpose}</small></div><Button variant="outline" onClick={() => unlinkDocument.mutate({ internalProjectId: project.id, documentId: document.id })}>Remove context</Button></article>)}{!currentDocumentLinks.length && <div className="empty-state">No documents linked. Add development plans, budgets, pro formas, estimates, diligence materials, or other existing library records when they are available.</div>}</div></>}</div>}
  </section>;
}

function ProjectEconomicsModelShell({ project, model, inputs, monthlyItems, readiness, documents, inputDocumentLinks, initializeModel, saveInput, saveMonthlyItem, linkInputDocument, unlinkInputDocument, onOpenRoi }: any) {
  const [inputDraft, setInputDraft] = useState({ area: "uses", category: "", name: "", value: "", unit: "usd", state: "missing", source: "", effective: "", owner: "", opportunityId: "", notes: "" });
  const [monthlyDraft, setMonthlyDraft] = useState({ month: "", phase: "", category: "", amount: "", state: "missing", source: "", effective: "", owner: "", notes: "" });
  const [inputDocumentDraft, setInputDocumentDraft] = useState({ inputId: "", documentId: "" });
  const isCedarwood = project?.projectName === "Cedarwood Flats";
  const currentInputIds = new Set(inputs.map((input: any) => input.id));
  const currentInputDocumentLinks = inputDocumentLinks.filter((link: any) => currentInputIds.has(link.modelInputId));
  const availableDocuments = documents.filter((document: any) => document.status === "current");
  const blueprint = isCedarwood ? [
    ["Uses of capital", "Land / acquisition · Site development · Building construction · Soft costs · Financing costs · FF&E · Contingency · Working capital · Other"],
    ["Operating model", "Units · Occupancy · Rental revenue · Other revenue · Operating expenses · NOI"],
    ["Sources of capital", "CE equity · JV / Facility · Equipment Finance · Grants & Incentives · Other"],
  ] : [
    ["Uses of capital", "Land / lease · Site development · Building · Production equipment · Robotics / automation · Technology · Soft costs · Contingency · Working capital"],
    ["Operating model", "Production capacity · Ramp / utilization · Product mix · Materials · Direct labor · Utilities · Maintenance · Logistics · Staffing · Fixed overhead · Revenue"],
    ["Sources of capital", "CE equity · JV / Facility · Equipment Finance · Grants & Incentives · Other financing"],
  ];
  const inputDocumentsFor = (inputId: number) => currentInputDocumentLinks.filter((link: any) => link.modelInputId === inputId).map((link: any) => documents.find((document: any) => document.id === link.documentId)).filter(Boolean);
  if (!model) return <Card className="project-economics-setup"><CardHeader><div className="kicker">PROJECT ECONOMICS · MODEL SHELL</div><CardTitle>Establish the 36-month analysis layer without assumptions</CardTitle></CardHeader><CardContent><p className="section-subtitle">The shell creates a single owner-scoped model linked to {project.projectName}. It records no cost, source, schedule, cash flow, return, or capital-opportunity data. All financial metrics remain unavailable until validated inputs are recorded.</p><div className="project-economics-blueprint">{blueprint.map(([label, detail]) => <div key={label}><b>{label}</b><span>{detail}</span></div>)}</div><Button disabled={initializeModel.isPending} onClick={() => initializeModel.mutate({ internalProjectId: project.id })}>{initializeModel.isPending ? "Creating model shell…" : `Create ${project.projectName} 36-month model shell`}</Button></CardContent></Card>;
  return <div className="project-economics-shell"><Card><CardHeader><div className="table-head"><div><div className="kicker">GOVERNED PROJECT ECONOMICS · SHELL</div><CardTitle>{model.modelName}</CardTitle></div><span className="roi-state missing">{model.modelStatus}</span></div></CardHeader><CardContent><div className="project-economics-metrics"><RoiMetric label="HORIZON" value={`${model.horizonMonths} MONTHS`} note="Month 1–36" /><RoiMetric label="MODEL START" value={model.modelStartDataState === "missing" ? "UNRECORDED" : "RECORDED"} note="No start date assumed" /><RoiMetric label="GOVERNED INPUTS" value={String(readiness?.recordedInputs ?? 0)} note={`${readiness?.missingInputs ?? 0} incomplete or missing`} /><RoiMetric label="RETURNS" value={readiness?.returnsAvailable ? "READY" : "UNAVAILABLE"} note={readiness?.returnStatus || "Unavailable — insufficient inputs"} /></div><div className="project-economics-unavailable"><b>{readiness?.returnStatus || "Unavailable — insufficient inputs"}</b><p>{readiness?.returnReason || "ROI, IRR, payback, distributions, and multiple remain unavailable until validated monthly inflows and outflows are recorded."}</p><Button variant="outline" onClick={onOpenRoi}>Open ROI / Returns</Button></div></CardContent></Card>
    <Card><CardHeader><div className="kicker">MODEL INPUT BLUEPRINT</div><CardTitle>Future inputs are grouped before they are valued</CardTitle></CardHeader><CardContent><div className="project-economics-blueprint">{blueprint.map(([label, detail]) => <div key={label}><b>{label}</b><span>{detail}</span></div>)}</div><p className="section-subtitle">Use the form below only when an input has a recorded value or a deliberately documented missing state. Blank values are never converted to zero.</p></CardContent></Card>
    <div className="project-economics-grid"><Card><CardHeader><div className="kicker">GOVERNED INPUT</div><CardTitle>Add uses, operations, or sources</CardTitle></CardHeader><CardContent><div className="internal-project-form-grid"><select value={inputDraft.area} onChange={(event) => setInputDraft({ ...inputDraft, area: event.target.value })}><option value="uses">Uses of capital</option><option value="operations">Operating model</option><option value="sources">Sources of capital</option></select><Input placeholder="Category *" value={inputDraft.category} onChange={(event) => setInputDraft({ ...inputDraft, category: event.target.value })} /><Input placeholder="Input name *" value={inputDraft.name} onChange={(event) => setInputDraft({ ...inputDraft, name: event.target.value })} /><Input inputMode="numeric" placeholder="Value" value={inputDraft.value} onChange={(event) => setInputDraft({ ...inputDraft, value: event.target.value })} /><select value={inputDraft.unit} onChange={(event) => setInputDraft({ ...inputDraft, unit: event.target.value })}><option value="usd">USD</option><option value="units">Units</option><option value="percentage_bps">Percentage (bps)</option><option value="hours">Hours</option><option value="other">Other</option></select><select value={inputDraft.state} onChange={(event) => setInputDraft({ ...inputDraft, state: event.target.value })}><option value="missing">State: missing</option><option value="actual">State: actual</option><option value="projected">State: projected</option><option value="estimated">State: estimated</option></select><Input placeholder="Source / evidence reference" value={inputDraft.source} onChange={(event) => setInputDraft({ ...inputDraft, source: event.target.value })} /><Input type="date" aria-label="Input effective date" value={inputDraft.effective} onChange={(event) => setInputDraft({ ...inputDraft, effective: event.target.value })} /><Input placeholder="Input owner" value={inputDraft.owner} onChange={(event) => setInputDraft({ ...inputDraft, owner: event.target.value })} /></div><Textarea rows={2} placeholder="Input notes, scope, or exclusions" value={inputDraft.notes} onChange={(event) => setInputDraft({ ...inputDraft, notes: event.target.value })} /><Button disabled={!inputDraft.category.trim() || !inputDraft.name.trim() || saveInput.isPending} onClick={() => { saveInput.mutate({ modelId: model.id, inputArea: inputDraft.area, inputCategory: inputDraft.category.trim(), inputName: inputDraft.name.trim(), value: roiNumber(inputDraft.value), valueUnit: inputDraft.unit, dataState: inputDraft.state, sourceReference: inputDraft.source.trim() || undefined, effectiveAt: inputDraft.effective ? new Date(`${inputDraft.effective}T00:00:00`) : undefined, ownerName: inputDraft.owner.trim() || undefined, notes: inputDraft.notes.trim() || undefined, sortOrder: inputs.length }); setInputDraft({ area: "uses", category: "", name: "", value: "", unit: "usd", state: "missing", source: "", effective: "", owner: "", opportunityId: "", notes: "" }); }}>{saveInput.isPending ? "Saving…" : "Save governed input"}</Button></CardContent></Card>
      <Card><CardHeader><div className="kicker">36-MONTH CASH-FLOW SCHEDULE</div><CardTitle>Record timing only when supported</CardTitle></CardHeader><CardContent><div className="project-economics-timeline"><span>Months 1–36</span>{Array.from({ length: 36 }, (_, index) => <b key={index}>{index + 1}</b>)}</div><div className="project-economics-phase-reference"><span>Predevelopment</span><span>Construction</span><span>Commissioning</span><span>Operating ramp</span></div><p className="section-subtitle">Phase timing is not yet assigned. Record a monthly item only with its phase, amount, source, effective date, owner, and state. Inflows are positive; capex, debt service, and operating outflows use negative amounts.</p><div className="internal-project-form-grid"><Input type="number" min="1" max="36" placeholder="Month 1–36 *" value={monthlyDraft.month} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, month: event.target.value })} /><select value={monthlyDraft.phase} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, phase: event.target.value })}><option value="">Phase *</option><option value="predevelopment">Predevelopment</option><option value="construction">Construction</option><option value="commissioning">Commissioning</option><option value="operating_ramp">Operating ramp</option></select><select value={monthlyDraft.category} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, category: event.target.value })}><option value="">Category *</option><option value="capex">Capex</option><option value="draw">Source draw</option><option value="operating_cash_flow">Operating cash flow</option><option value="debt_service">Debt service</option><option value="grant_disbursement">Grant disbursement</option><option value="revenue_collections">Revenue collections</option></select><Input inputMode="numeric" placeholder="Amount" value={monthlyDraft.amount} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, amount: event.target.value })} /><select value={monthlyDraft.state} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, state: event.target.value })}><option value="missing">State: missing</option><option value="actual">State: actual</option><option value="projected">State: projected</option><option value="estimated">State: estimated</option></select><Input placeholder="Source / evidence reference" value={monthlyDraft.source} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, source: event.target.value })} /><Input type="date" aria-label="Monthly item effective date" value={monthlyDraft.effective} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, effective: event.target.value })} /><Input placeholder="Input owner" value={monthlyDraft.owner} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, owner: event.target.value })} /></div><Textarea rows={2} placeholder="Monthly item notes" value={monthlyDraft.notes} onChange={(event) => setMonthlyDraft({ ...monthlyDraft, notes: event.target.value })} /><Button disabled={!monthlyDraft.month || !monthlyDraft.phase || !monthlyDraft.category || saveMonthlyItem.isPending} onClick={() => { saveMonthlyItem.mutate({ modelId: model.id, monthIndex: Number(monthlyDraft.month), phase: monthlyDraft.phase, category: monthlyDraft.category, amount: roiNumber(monthlyDraft.amount), dataState: monthlyDraft.state, sourceReference: monthlyDraft.source.trim() || undefined, effectiveAt: monthlyDraft.effective ? new Date(`${monthlyDraft.effective}T00:00:00`) : undefined, ownerName: monthlyDraft.owner.trim() || undefined, notes: monthlyDraft.notes.trim() || undefined }); setMonthlyDraft({ month: "", phase: "", category: "", amount: "", state: "missing", source: "", effective: "", owner: "", notes: "" }); }}>{saveMonthlyItem.isPending ? "Saving…" : "Save monthly item"}</Button></CardContent></Card></div>
    <div className="project-economics-records"><Card><CardHeader><div className="kicker">RECORDED MODEL INPUTS</div><CardTitle>Inputs retain evidence and data state</CardTitle></CardHeader><CardContent>{inputs.map((input: any) => <article key={input.id}><div><b>{input.inputName}</b><span>{input.inputArea} · {input.inputCategory} · {input.valueUnit}</span><small>{input.sourceReference || "No source reference recorded"}{input.ownerName ? ` · Owner: ${input.ownerName}` : ""}{input.effectiveAt ? ` · Effective ${new Date(input.effectiveAt).toLocaleDateString()}` : ""}</small>{inputDocumentsFor(input.id).map((document: any) => <small key={document.id}>Evidence: {document.name} · {document.version} <button type="button" className="inline-action" onClick={() => unlinkInputDocument.mutate({ modelInputId: input.id, documentId: document.id })}>remove</button></small>)}</div><div><strong>{input.dataState === "missing" ? "Not yet recorded" : input.value ?? "Not yet recorded"}</strong><span className={`roi-state ${input.dataState}`}>{input.dataState}</span></div></article>)}{!inputs.length && <div className="empty-state">No model inputs recorded. The shell deliberately starts blank.</div>}</CardContent></Card><Card><CardHeader><div className="kicker">INPUT EVIDENCE CONTEXT</div><CardTitle>Attach existing library documents to a model input</CardTitle></CardHeader><CardContent><p className="section-subtitle">Files remain in the Document Library. This creates an auditable link to a specific model input rather than copying a file or burying its source in notes.</p><div className="inline-form"><select value={inputDocumentDraft.inputId} onChange={(event) => setInputDocumentDraft({ ...inputDocumentDraft, inputId: event.target.value })}><option value="">Select model input</option>{inputs.map((input: any) => <option key={input.id} value={input.id}>{input.inputName} · {input.dataState}</option>)}</select><select value={inputDocumentDraft.documentId} onChange={(event) => setInputDocumentDraft({ ...inputDocumentDraft, documentId: event.target.value })}><option value="">Select current library document</option>{availableDocuments.map((document: any) => <option key={document.id} value={document.id}>{document.name} · {document.version}</option>)}</select><Button disabled={!inputDocumentDraft.inputId || !inputDocumentDraft.documentId || linkInputDocument.isPending} onClick={() => { linkInputDocument.mutate({ modelInputId: Number(inputDocumentDraft.inputId), documentId: Number(inputDocumentDraft.documentId) }); setInputDocumentDraft({ inputId: "", documentId: "" }); }}>Attach evidence</Button></div></CardContent></Card></div>
    <Card><CardHeader><div className="kicker">RECORDED MONTHLY ITEMS</div><CardTitle>Cash-flow inputs are sparse until evidence exists</CardTitle></CardHeader><CardContent><div className="project-economics-monthly-list">{monthlyItems.map((item: any) => <article key={item.id}><b>Month {item.monthIndex}</b><span>{item.phase.replaceAll("_", " ")} · {item.category.replaceAll("_", " ")}</span><strong>{item.dataState === "missing" ? "Not yet recorded" : item.amount ?? "Not yet recorded"}</strong><span className={`roi-state ${item.dataState}`}>{item.dataState}</span></article>)}{!monthlyItems.length && <div className="empty-state">No monthly cash-flow item is recorded. ROI, IRR, payback, distributions, and multiple remain unavailable.</div>}</div></CardContent></Card>
  </div>;
}

export default App;
